class TwoStacks {
  // The array that holds both stacks
  var arr: array<int>;
  // Top indices for both stacks (s1 grows from left, s2 grows from right)
  var top1: int;
  var top2: int;
  // Maximum capacity for each stack
  const stackLimit: int;

  // Ghost variables for verification
  ghost var s1Contents: seq<int>;
  ghost var s2Contents: seq<int>;

  // Constructor
  constructor (limit: int)
    requires limit > 0
    ensures top1 == 0 && top2 == arr.Length - 1
    ensures stackLimit == limit
    ensures s1Contents == [] && s2Contents == []
    ensures arr.Length == 2 * limit
  {
    stackLimit := limit;
    arr := new int[2 * limit];
    top1 := 0;
    top2 := arr.Length - 1;
    s1Contents := [];
    s2Contents := [];
  }

  // Predicates for stack states
  predicate s1IsEmpty()
    reads this
  {
    top1 == 0
  }

  predicate s2IsEmpty()
    reads this
  {
    top2 == arr.Length - 1
  }

  predicate s1IsFull()
    reads this
  {
    top1 == stackLimit
  }

  predicate s2IsFull()
    reads this
  {
    top2 == arr.Length - 1 - stackLimit
  }

  // Invariant ensuring the stacks don't overlap and respect limits
  predicate Valid()
    reads this
  {
    && arr != null
    && arr.Length == 2 * stackLimit
