class TwoStacks {
  // The array that holds both stacks
  var arr: array<int>
  // Maximum size of the array
  ghost var maxSize: int
  // Current top of stack 1 (grows from left)
  var top1: int
  // Current top of stack 2 (grows from right)
  var top2: int

  // Invariant: array size is positive
  invariant arr != null && arr.Length > 0
  invariant maxSize == arr.Length

  // Invariant: stack tops are within bounds and don't overlap
  invariant 0 <= top1 && top1 <= maxSize
  invariant -1 <= top2 && top2 <= maxSize - 1
  invariant top2 == maxSize - 1 || top1 <= top2 + 1

  // Stack 1 grows from index 0 upward
  // Stack 2 grows from index maxSize-1 downward

  // Constructor
  constructor(initSize: int)
    requires initSize > 0
    ensures arr != null && arr.Length == initSize
    ensures top1 == 0 && top2 == initSize - 1
    ensures maxSize == initSize
  {
    arr := new int[initSize];
    maxSize := initSize;
    top1 := 0;
    top2 := initSize - 1;
  }

  // Check if stack 1 is empty
  method IsEmpty1() returns (empty: bool)
    ensures empty == (top1 == 0)
  {
    empty := top1 == 0;
  }

  // Check if stack 2 is empty  
  method IsEmpty2() returns (empty: bool)
    ensures empty == (top2 == maxSize - 1)
  {
    empty := top2 == maxSize - 1;
  }

  // Check if stack 1 is full
  method IsFull1() returns (full: bool)
    ensures full == (top1 > top2 + 1)
  {
