    ensures success ==> top1 == old(top1) + 1
    ensures success ==> arr[old(top1)] == value
    ensures !success ==> old(IsFull1())
  {
    if top1 > top2 + 1 {
      success := false;
    } else {
      arr[top1] := value;
      top1 := top1 + 1;
