    ensures success ==> !IsEmpty2()
    ensures success ==> value == arr[top2 + 1]
    ensures !success ==> IsEmpty2()
  {
    if top2 == maxSize - 1 {
      success := false;
      value := 0;
    } else {
      value := arr[top2 + 1];
      success := true;
    }
  }

