  var leftStack: array<T>;
  var rightStack: array<T>;

  // Pointers for each stack
  var leftTop: int;
  var rightTop: int;

  // Capacity of each stack (they share the same total capacity)
  var capacity: int;

  // Ghost variables for verification
  ghost var leftElements: seq<T>;
  ghost var rightElements: seq<T>;

  // Constructor
  constructor (cap: int)
    requires cap > 0
    ensures capacity == cap
    ensures leftTop == 0 && rightTop == 0
    ensures leftElements == [] && rightElements == []
  {
    capacity := cap;
    leftStack := new T[cap];
    rightStack := new T[cap];
    leftTop := 0;
    rightTop := 0;
    leftElements := [];
    rightElements := [];
  }

