    var stack1: Stack
    var count: nat
    const maxSize: nat
    ghost var ghostStackGuard0: seq<int>
    ghost var ghostStackGuard1: seq<int>

    // Constructor
    constructor Init(maxSize': nat)
      requires maxSize' > 0
      ensures maxSize == maxSize'
      ensures stack0.size == 0 && stack1.size == 0
      ensures count == 0
      ensures |stack0.elements| == 0 && |stack1.elements| == 0
      ensures ghostStackGuard0 == [] && ghostStackGuard1 == []
