    predicate ValidState()
      reads this
    {
      && stack0.size <= maxSize
      && stack1.size <= maxSize
      && stack0.size == |stack0.elements|
      && stack1.size == |stack1.elements|
      && count == stack0.size + stack1.size
      && count <= 2 * maxSize
      && ghostStackGuard0 == stack0.elements
